// Guard: the render must only use audio generated by scripts/synth-audio.mjs.
import fs from 'node:fs';
import path from 'node:path';
const dir = new URL('../public/sfx/', import.meta.url).pathname;
const allowed = new Set(['move', 'capture', 'whoosh', 'swish', 'riser', 'tick', 'hit_intro', 'impact', 'fall1', 'fall2', 'brand', 'music'].map((n) => n + '.wav'));
const bad = fs.readdirSync(dir).filter((f) => !allowed.has(f));
if (bad.length) { console.error('Unexpected audio files in public/sfx (only synthesised audio is allowed):', bad.join(', ')); process.exit(1); }
const missing = [...allowed].filter((f) => !fs.existsSync(path.join(dir, f)));
if (missing.length) { console.error('Missing synthesised audio:', missing.join(', ')); process.exit(1); }
console.log('Audio check passed: only the 12 synthesised files are present.');
